<template><div><h1 class="text-3xl font-bold">Tableau de bord</h1><p class="mt-2 text-[var(--muted)]">Vue rapide du moteur de contenu et d’acquisition.</p><div class="mt-8 grid gap-5 sm:grid-cols-2 xl:grid-cols-4"><div v-for="card in cards" :key="card.label" class="card"><p class="font-mono text-[10px] uppercase tracking-wider text-[var(--muted)]">{{ card.label }}</p><p class="mt-3 text-4xl font-bold text-violet-700 dark:text-violet-300">{{ card.value }}</p></div></div></div></template>
<script setup lang="ts">definePageMeta({middleware:'admin',layout:'admin',i18n:{locales:['fr']}});useSeoMeta({title:'Tableau de bord',robots:'noindex,nofollow'});const {data}=await useFetch('/api/admin/dashboard',{default:()=>({leads:0,resources:0,articles:0,newLeads:0,projects:0,testimonialsPending:0})});const cards=computed(()=>[{label:'Leads',value:data.value.leads},{label:'Nouveaux',value:data.value.newLeads},{label:'Réalisations publiées',value:data.value.projects},{label:'Avis à modérer',value:data.value.testimonialsPending},{label:'Ressources',value:data.value.resources},{label:'Articles',value:data.value.articles}])</script>
